-- =============================================================================
-- Q4 FULL: Return Trip Funnel Throughput
-- BASE = onward / forward TRANSACTORS (booked A→B)
-- Then funnel on RETURN route B→A within 14 days of onward booking:
--   Return SRP → SL → CustInfo → TCO → PaymentLand → Confirm
-- Cuts: destination_tier (onward dest) × DBD (onward) × user_type (+ OVERALL)
-- Android IND | Mehar listing | onward DOI 24 Aug – 6 Sep 2026 IST
-- No calendar DOI day grain
-- =============================================================================

