  ) AS t(dest_id, tier)
),
onward_txn AS (
  SELECT
    b.rb_user_id,
    b.tin AS onward_tin,
    b.source_location_id AS src_id,
    b.destination_location_id AS dest_id,
    ctm.tier AS destination_tier,
    b.time_of_event AS onward_txn_time,
    UPPER(TRIM(COALESCE(b.user_type, ''))) AS user_type,
    CASE
      WHEN DATE_DIFF(
             'day',
             CAST(DATE_TRUNC('day', AT_TIMEZONE(b.date_of_issue, 'Asia/Kolkata')) AS DATE),
             CAST(DATE_TRUNC('day', AT_TIMEZONE(b.date_of_journey, 'Asia/Kolkata')) AS DATE)
           ) <= 0 THEN '0. Same Day'
      WHEN DATE_DIFF(
             'day',
             CAST(DATE_TRUNC('day', AT_TIMEZONE(b.date_of_issue, 'Asia/Kolkata')) AS DATE),
             CAST(DATE_TRUNC('day', AT_TIMEZONE(b.date_of_journey, 'Asia/Kolkata')) AS DATE)
           ) = 1 THEN '1. DBD 1'
      WHEN DATE_DIFF(
             'day',
             CAST(DATE_TRUNC('day', AT_TIMEZONE(b.date_of_issue, 'Asia/Kolkata')) AS DATE),
             CAST(DATE_TRUNC('day', AT_TIMEZONE(b.date_of_journey, 'Asia/Kolkata')) AS DATE)
           ) = 2 THEN '2. DBD 2'
      WHEN DATE_DIFF(
             'day',
             CAST(DATE_TRUNC('day', AT_TIMEZONE(b.date_of_issue, 'Asia/Kolkata')) AS DATE),
             CAST(DATE_TRUNC('day', AT_TIMEZONE(b.date_of_journey, 'Asia/Kolkata')) AS DATE)
           ) BETWEEN 3 AND 7 THEN '3. DBD 3-7'
      ELSE '4. DBD 8+'
    END AS dbd
  FROM transaction.bus_ticket_events b
  INNER JOIN city_tier_map ctm ON b.destination_location_id = ctm.dest_id
  WHERE b.country_code = 'IND'
    AND b.event_type = 101
    AND b.tin IS NOT NULL
    AND b.rb_user_id > 0
    AND b.sales_channel IN ('RB:MOBILEWEB#droidapp', 'DROIDAPP')
    AND b.date_of_issue >= TIMESTAMP '2026-08-23 18:30:00'
    AND b.date_of_issue <  TIMESTAMP '2026-09-06 18:30:00'
),
cohort_users AS (
  SELECT DISTINCT rb_user_id FROM onward_txn
),
-- Return SRP among onward bookers on reverse route (dedupe 1 row per session+route)
return_srp AS (
  SELECT
    destination_tier,
    dbd,
    user_type,
    rb_user_id,
    mri_session_id,
    route_id
  FROM (
    SELECT
      o.destination_tier,
      o.dbd,
      o.user_type,
      o.rb_user_id,
      s.mri_session_id,
      s.route_id,
      ROW_NUMBER() OVER (
        PARTITION BY s.mri_session_id, s.route_id
        ORDER BY o.onward_txn_time DESC
      ) AS rn
    FROM onward_txn o
    INNER JOIN user_interaction.search_route_details s
      ON s.rb_user_id = o.rb_user_id
     AND s.src_id = o.dest_id
     AND s.dest_id = o.src_id
     AND s.country = 'IND'
     AND s.os = 'Android'
     AND s.channel = 'MOBILE_APP'
     AND s.status = 200
     AND s.mri_session_id IS NOT NULL
     AND s.__time > o.onward_txn_time
     AND s.__time <= o.onward_txn_time + INTERVAL '14' DAY
     AND s.__time > TIMESTAMP '2026-08-23 18:30:00'
     AND s.__time <  TIMESTAMP '2026-09-20 18:30:00'
  ) x
  WHERE rn = 1
),
-- Funnel steps in extended window (return can land after onward window)
sl_deduped AS (
  SELECT DISTINCT mri_session_id, route_id
  FROM user_interaction.seat_layout_details
  WHERE __time > TIMESTAMP '2026-08-23 18:30:00'
    AND __time <  TIMESTAMP '2026-09-20 18:30:00'
    AND country = 'IND'
),
mpax_deduped AS (
  SELECT DISTINCT mri_session_id, route_id
  FROM user_interaction.cust_info_details
  WHERE __time > TIMESTAMP '2026-08-23 18:30:00'
    AND __time <  TIMESTAMP '2026-09-20 18:30:00'
    AND country = 'IND'
),
tco_deduped AS (
  SELECT DISTINCT mri_session_id, route_id
  FROM user_interaction.create_order_details
  WHERE __time > TIMESTAMP '2026-08-23 18:30:00'
    AND __time <  TIMESTAMP '2026-09-20 18:30:00'
    AND country = 'IND'
),
orderinfo_deduped AS (
  SELECT DISTINCT mri_session_id, route_id
  FROM user_interaction.order_info_details
  WHERE __time > TIMESTAMP '2026-08-23 18:30:00'
    AND __time <  TIMESTAMP '2026-09-20 18:30:00'
    AND country = 'IND'
),
confirm_deduped AS (
  SELECT mri_session_id, route_id, COUNT(DISTINCT tin) AS tin_count
  FROM user_interaction.confirm_order_details
  WHERE __time > TIMESTAMP '2026-08-23 18:30:00'
    AND __time <  TIMESTAMP '2026-09-20 18:30:00'
    AND country = 'IND'
    AND status = 200
    AND tin IS NOT NULL
    AND tin NOT IN ('', 'null')
  GROUP BY 1, 2
),
return_funnel AS (
  SELECT
    r.destination_tier,
    r.dbd,
    r.user_type,
    r.rb_user_id,
    r.mri_session_id,
    sl.mri_session_id AS sl_sid,
    pax.mri_session_id AS pax_sid,
    tco.mri_session_id AS tco_sid,
    oi.mri_session_id AS oi_sid,
    conf.mri_session_id AS conf_sid,
    conf.tin_count
  FROM return_srp r
  LEFT JOIN sl_deduped sl
    ON r.mri_session_id = sl.mri_session_id AND r.route_id = sl.route_id
  LEFT JOIN mpax_deduped pax
    ON r.mri_session_id = pax.mri_session_id AND r.route_id = pax.route_id
  LEFT JOIN tco_deduped tco
    ON r.mri_session_id = tco.mri_session_id AND r.route_id = tco.route_id
  LEFT JOIN orderinfo_deduped oi
    ON r.mri_session_id = oi.mri_session_id AND r.route_id = oi.route_id
  LEFT JOIN confirm_deduped conf
    ON r.mri_session_id = conf.mri_session_id AND r.route_id = conf.route_id
),
onward_base AS (
  SELECT
    CASE WHEN GROUPING(destination_tier) = 1 THEN 'OVERALL' ELSE destination_tier END AS destination_tier,
    dbd,
    user_type,
    COUNT(DISTINCT rb_user_id) AS onward_bookers,
    COUNT(DISTINCT onward_tin) AS onward_txns
  FROM onward_txn
  GROUP BY GROUPING SETS ((destination_tier, dbd, user_type), (dbd, user_type))
),
funnel_agg AS (
  SELECT
    CASE WHEN GROUPING(destination_tier) = 1 THEN 'OVERALL' ELSE destination_tier END AS destination_tier,
    dbd,
    user_type,
    COUNT(DISTINCT rb_user_id) AS return_srp_users,
    COUNT(DISTINCT mri_session_id) AS return_srpload,
    COUNT(DISTINCT sl_sid) AS return_slload,
    COUNT(DISTINCT pax_sid) AS return_custinfo_sessions,
    COUNT(DISTINCT tco_sid) AS return_tco_sessions,
    COUNT(DISTINCT oi_sid) AS return_payment_land_sessions,
    COUNT(DISTINCT conf_sid) AS return_confirm_sessions,
    COALESCE(SUM(tin_count), 0) AS return_tin
  FROM return_funnel
  GROUP BY GROUPING SETS ((destination_tier, dbd, user_type), (dbd, user_type))
)
SELECT
  b.destination_tier,
  b.dbd,
  b.user_type,
  b.onward_bookers,
  b.onward_txns,
  COALESCE(f.return_srp_users, 0) AS return_srp_users,
  COALESCE(f.return_srpload, 0) AS return_srpload,
  COALESCE(f.return_slload, 0) AS return_slload,
  COALESCE(f.return_custinfo_sessions, 0) AS return_custinfo_sessions,
  COALESCE(f.return_tco_sessions, 0) AS return_tco_sessions,
  COALESCE(f.return_payment_land_sessions, 0) AS return_payment_land_sessions,
  COALESCE(f.return_confirm_sessions, 0) AS return_confirm_sessions,
  COALESCE(f.return_tin, 0) AS return_tin,
  -- Attach to onward bookers
  ROUND(100.0 * COALESCE(f.return_srp_users, 0) / NULLIF(b.onward_bookers, 0), 2)
    AS pct_onward_bookers_with_return_srp,
  ROUND(100.0 * COALESCE(f.return_confirm_sessions, 0) / NULLIF(b.onward_bookers, 0), 2)
    AS pct_onward_bookers_with_return_confirm,
  -- Return funnel CRs (among return SRP sessions)
  ROUND(100.0 * COALESCE(f.return_slload, 0) / NULLIF(f.return_srpload, 0), 2) AS return_srp_to_sl_pct,
  ROUND(100.0 * COALESCE(f.return_custinfo_sessions, 0) / NULLIF(f.return_slload, 0), 2) AS return_sl_to_custinfo_pct,
  ROUND(100.0 * COALESCE(f.return_tco_sessions, 0) / NULLIF(f.return_custinfo_sessions, 0), 2) AS return_custinfo_to_tco_pct,
  ROUND(100.0 * COALESCE(f.return_payment_land_sessions, 0) / NULLIF(f.return_tco_sessions, 0), 2) AS return_tco_to_pay_pct,
  ROUND(100.0 * COALESCE(f.return_confirm_sessions, 0) / NULLIF(f.return_payment_land_sessions, 0), 2) AS return_pay_to_confirm_pct,
  ROUND(100.0 * COALESCE(f.return_confirm_sessions, 0) / NULLIF(f.return_srpload, 0), 2) AS return_srp_to_confirm_pct,
  ROUND(100.0 * COALESCE(f.return_tin, 0) / NULLIF(f.return_srpload, 0), 2) AS return_tin_per_srp_pct
FROM onward_base b
LEFT JOIN funnel_agg f
  ON b.destination_tier = f.destination_tier
 AND b.dbd = f.dbd
 AND b.user_type = f.user_type
ORDER BY
  CASE b.destination_tier
    WHEN 'OVERALL' THEN 0 WHEN 'Tier 1' THEN 1 WHEN 'Tier 2' THEN 2
    WHEN 'Tier 3' THEN 3 WHEN 'Pilgrim' THEN 4 WHEN 'Leisure' THEN 5 ELSE 9
  END,
  b.dbd, b.user_type;
